import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        grid.append(row)

    visited = [[False for _ in range(m)] for _ in range(n)]
    queue = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and (i == 0 or i == n - 1 or j == 0 or j == m - 1):
                if not visited[i][j]:
                    visited[i][j] = True
                    queue.append((i, j))

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    head = 0
    while head < len(queue):
        r, c = queue[head]
        head += 1
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if grid[nr][nc] == 1 and not visited[nr][nc]:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    count = 0
    for i in range(n):
        for j in range(m): if grid[i][j] == 1 and not visited[i][j]:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
